-- ============================================================
-- Topic Quiz Questions — content insert
-- 18 topics x 4 languages (en/ar/fr/sw) = 72 rows.
-- Run this AFTER schema.sql (which creates the topic_questions table)
-- and AFTER uploading the images in assets/quiz/ alongside the app,
-- OR after uploading those images to Supabase Storage and swapping
-- the image paths below for the storage public URLs.
-- ============================================================

on conflict (topic_key, language) do update set
  question_text = excluded.question_text,
  correct_answer_text = excluded.correct_answer_text,
  incorrect_answer_text = excluded.incorrect_answer_text,
  correct_image_url = excluded.correct_image_url,
  incorrect_image_url = excluded.incorrect_image_url;
