insert into topic_questions
  (topic_key, language, question_text, correct_answer_text, incorrect_answer_text, correct_image_url, incorrect_image_url)
values
('welcome', 'en', 'Before starting work on any site, what should every team member do first?', 'Complete the safety induction and understand the emergency procedures', 'Go straight to their post and ask questions later if needed', 'assets/quiz/welcome_correct.jpg', 'assets/quiz/welcome_incorrect.jpg'),
('welcome', 'ar', 'قبل بدء العمل في أي موقع، ماذا يجب على كل فرد من الفريق أن يفعل أولاً؟', 'إكمال التوجيه الأمني وفهم إجراءات الطوارئ', 'التوجه مباشرة إلى موقعه وطرح الأسئلة لاحقاً إذا لزم الأمر', 'assets/quiz/welcome_correct.jpg', 'assets/quiz/welcome_incorrect.jpg'),
('welcome', 'fr', 'Avant de commencer le travail sur un site, que doit faire chaque membre de l''équipe en premier ?', 'Suivre l''induction sécurité et comprendre les procédures d''urgence', 'Se rendre directement à son poste et poser des questions plus tard si besoin', 'assets/quiz/welcome_correct.jpg', 'assets/quiz/welcome_incorrect.jpg'),
('welcome', 'sw', 'Kabla ya kuanza kazi kwenye eneo lolote, kila mwanachama wa timu anapaswa kufanya nini kwanza?', 'Kukamilisha mafunzo ya usalama na kuelewa taratibu za dharura', 'Kwenda moja kwa moja kituoni na kuuliza maswali baadaye ikihitajika', 'assets/quiz/welcome_correct.jpg', 'assets/quiz/welcome_incorrect.jpg'),
('ppe', 'en', 'When is Personal Protective Equipment (PPE) required in a designated area?', 'At all times, worn correctly and completely', 'Only when a supervisor happens to be watching', 'assets/quiz/ppe_correct.jpg', 'assets/quiz/ppe_incorrect.jpg'),
('ppe', 'ar', 'متى يكون ارتداء معدات الحماية الشخصية (PPE) إلزامياً في المنطقة المخصصة؟', 'في جميع الأوقات، ويتم ارتداؤها بشكل صحيح وكامل', 'فقط عندما يكون المشرف يراقب', 'assets/quiz/ppe_correct.jpg', 'assets/quiz/ppe_incorrect.jpg'),
('ppe', 'fr', 'Quand l''équipement de protection individuelle (EPI) est-il requis dans une zone désignée ?', 'En permanence, porté correctement et intégralement', 'Seulement quand un superviseur regarde', 'assets/quiz/ppe_correct.jpg', 'assets/quiz/ppe_incorrect.jpg'),
('ppe', 'sw', 'Vifaa vya kinga binafsi (PPE) vinahitajika lini katika eneo maalum?', 'Wakati wote, vikiwa vimevaliwa kwa usahihi na kikamilifu', 'Wakati tu msimamizi anapoangalia', 'assets/quiz/ppe_correct.jpg', 'assets/quiz/ppe_incorrect.jpg'),
('access_control', 'en', 'What must a person show to enter a restricted or accredited area?', 'Valid, visible accreditation checked against the access list', 'A verbal claim that they are allowed in, without any pass', 'assets/quiz/access_correct.jpg', 'assets/quiz/access_incorrect.jpg'),
('access_control', 'ar', 'ماذا يجب على الشخص إظهاره لدخول منطقة مقيدة أو معتمدة؟', 'اعتماد صالح وظاهر يتم التحقق منه مقابل قائمة الدخول', 'الادعاء الشفهي بأنه مسموح له بالدخول دون أي تصريح', 'assets/quiz/access_correct.jpg', 'assets/quiz/access_incorrect.jpg'),
('access_control', 'fr', 'Que doit présenter une personne pour entrer dans une zone réglementée ou accréditée ?', 'Une accréditation valide et visible, vérifiée sur la liste d''accès', 'Une simple affirmation verbale, sans aucun laissez-passer', 'assets/quiz/access_correct.jpg', 'assets/quiz/access_incorrect.jpg'),
('access_control', 'sw', 'Mtu anapaswa kuonyesha nini ili kuingia eneo lenye vikwazo au linalohitaji kibali?', 'Kibali halali na kinachoonekana, kilichothibitishwa dhidi ya orodha ya ufikiaji', 'Kudai kwa maneno tu kuwa ameruhusiwa bila kibali chochote', 'assets/quiz/access_correct.jpg', 'assets/quiz/access_incorrect.jpg'),
('emergency', 'en', 'If an alarm sounds and evacuation begins, what is the correct action?', 'Calmly follow the marked evacuation route to the assembly point', 'Stop to collect personal belongings before leaving the area', 'assets/quiz/emergency_correct.jpg', 'assets/quiz/emergency_incorrect.jpg'),
('emergency', 'ar', 'إذا انطلق جرس الإنذار وبدأ الإخلاء، ما هو الإجراء الصحيح؟', 'اتباع مسار الإخلاء المحدد بهدوء إلى نقطة التجمع', 'التوقف لجمع الأغراض الشخصية قبل مغادرة المنطقة', 'assets/quiz/emergency_correct.jpg', 'assets/quiz/emergency_incorrect.jpg'),
('emergency', 'fr', 'Si une alarme retentit et que l''évacuation commence, quelle est l''action correcte ?', 'Suivre calmement l''itinéraire d''évacuation balisé jusqu''au point de rassemblement', 'S''arrêter pour récupérer ses affaires personnelles avant de quitter la zone', 'assets/quiz/emergency_correct.jpg', 'assets/quiz/emergency_incorrect.jpg'),
('emergency', 'sw', 'Kengele ikilia na uhamishaji ukaanza, hatua sahihi ni ipi?', 'Kufuata kwa utulivu njia ya kutoka iliyowekwa alama hadi eneo la kukusanyika', 'Kusimama kukusanya vitu binafsi kabla ya kuondoka eneo hilo', 'assets/quiz/emergency_correct.jpg', 'assets/quiz/emergency_incorrect.jpg'),
('incident_reporting', 'en', 'You witness a near-miss (something that almost caused injury). What should you do?', 'Report it immediately to your supervisor or safety officer', 'Say nothing since no one was actually hurt', 'assets/quiz/incident_correct.jpg', 'assets/quiz/incident_incorrect.jpg'),
('incident_reporting', 'ar', 'شهدت حادثاً كاد أن يقع (شيء كاد أن يسبب إصابة). ماذا يجب أن تفعل؟', 'الإبلاغ عنه فوراً للمشرف أو مسؤول السلامة', 'عدم قول أي شيء لأن أحداً لم يُصب فعلياً', 'assets/quiz/incident_correct.jpg', 'assets/quiz/incident_incorrect.jpg'),
('incident_reporting', 'fr', 'Vous êtes témoin d''un presqu''accident (quelque chose qui a failli causer une blessure). Que devez-vous faire ?', 'Le signaler immédiatement à votre superviseur ou responsable sécurité', 'Ne rien dire puisque personne n''a été réellement blessé', 'assets/quiz/incident_correct.jpg', 'assets/quiz/incident_incorrect.jpg'),
('incident_reporting', 'sw', 'Umeshuhudia tukio lililokaribia kusababisha jeraha. Unapaswa kufanya nini?', 'Kuripoti mara moja kwa msimamizi au afisa usalama', 'Kutosema chochote kwa sababu hakuna aliyeumia kihalisi', 'assets/quiz/incident_correct.jpg', 'assets/quiz/incident_incorrect.jpg'),
('crowd_management', 'en', 'You notice early signs of overcrowding or crowd distress in your area. What should you do?', 'Alert your supervisor immediately so it can be managed before it becomes dangerous', 'Wait to see if it resolves on its own before saying anything', 'assets/quiz/crowd_correct.jpg', 'assets/quiz/crowd_incorrect.jpg'),
('crowd_management', 'ar', 'لاحظت علامات مبكرة على الاكتظاظ أو ضيق الحشد في منطقتك. ماذا يجب أن تفعل؟', 'تنبيه المشرف فوراً حتى يمكن التعامل مع الأمر قبل أن يصبح خطيراً', 'الانتظار لترى ما إذا كان الأمر سيُحل من تلقاء نفسه قبل قول أي شيء', 'assets/quiz/crowd_correct.jpg', 'assets/quiz/crowd_incorrect.jpg'),
('crowd_management', 'fr', 'Vous remarquez des signes précoces de surpeuplement ou de détresse de la foule dans votre zone. Que devez-vous faire ?', 'Alerter immédiatement votre superviseur pour que la situation soit gérée avant de devenir dangereuse', 'Attendre de voir si cela se résout tout seul avant de le signaler', 'assets/quiz/crowd_correct.jpg', 'assets/quiz/crowd_incorrect.jpg'),
('crowd_management', 'sw', 'Umeona dalili za awali za msongamano au dhiki ya umati katika eneo lako. Unapaswa kufanya nini?', 'Kumjulisha msimamizi wako mara moja ili hali idhibitiwe kabla haijawa hatari', 'Kusubiri kuona kama itajitatua yenyewe kabla ya kusema chochote', 'assets/quiz/crowd_correct.jpg', 'assets/quiz/crowd_incorrect.jpg'),
('use_of_force', 'en', 'What is the correct first response when a situation starts to escalate?', 'Attempt verbal de-escalation and call for backup if needed', 'Immediately use physical force to control the person', 'assets/quiz/force_correct.jpg', 'assets/quiz/force_incorrect.jpg'),
('use_of_force', 'ar', 'ما هو رد الفعل الأول الصحيح عندما يبدأ الموقف بالتصعيد؟', 'محاولة التهدئة اللفظية وطلب الدعم إذا لزم الأمر', 'استخدام القوة الجسدية فوراً للسيطرة على الشخص', 'assets/quiz/force_correct.jpg', 'assets/quiz/force_incorrect.jpg'),
('use_of_force', 'fr', 'Quelle est la première réaction correcte lorsqu''une situation commence à s''envenimer ?', 'Tenter une désescalade verbale et appeler du renfort si nécessaire', 'Utiliser immédiatement la force physique pour maîtriser la personne', 'assets/quiz/force_correct.jpg', 'assets/quiz/force_incorrect.jpg'),
('use_of_force', 'sw', 'Ni hatua gani sahihi ya kwanza wakati hali inapoanza kuzidi kuwa mbaya?', 'Kujaribu kutuliza kwa maneno na kuomba msaada ikihitajika', 'Kutumia nguvu za kimwili mara moja kumdhibiti mtu', 'assets/quiz/force_correct.jpg', 'assets/quiz/force_incorrect.jpg'),
('communication', 'en', 'What is the correct way to report an issue over the radio?', 'Clearly, calmly, and following your team''s agreed radio protocol', 'Shouting urgently without giving any location or detail', 'assets/quiz/comm_correct.jpg', 'assets/quiz/comm_incorrect.jpg'),
('communication', 'ar', 'ما هي الطريقة الصحيحة للإبلاغ عن مشكلة عبر جهاز اللاسلكي؟', 'بوضوح وهدوء، باتباع بروتوكول اللاسلكي المتفق عليه في فريقك', 'الصراخ بشكل عاجل دون ذكر أي موقع أو تفاصيل', 'assets/quiz/comm_correct.jpg', 'assets/quiz/comm_incorrect.jpg'),
('communication', 'fr', 'Quelle est la bonne façon de signaler un problème par radio ?', 'Clairement, calmement, et en suivant le protocole radio convenu par votre équipe', 'Crier avec urgence sans donner ni lieu ni détail', 'assets/quiz/comm_correct.jpg', 'assets/quiz/comm_incorrect.jpg'),
('communication', 'sw', 'Ni njia gani sahihi ya kuripoti tatizo kupitia redio?', 'Kwa uwazi na utulivu, ukifuata taratibu za redio zilizokubaliwa na timu yako', 'Kupiga kelele kwa haraka bila kutoa eneo au maelezo yoyote', 'assets/quiz/comm_correct.jpg', 'assets/quiz/comm_incorrect.jpg'),
('heat_wellbeing', 'en', 'Working outdoors in Gulf heat, what should a team member do regularly?', 'Take scheduled hydration breaks in shade or cool areas', 'Push through without breaks to finish the shift faster', 'assets/quiz/heat_correct.jpg', 'assets/quiz/heat_incorrect.jpg'),
('heat_wellbeing', 'ar', 'عند العمل في الهواء الطلق في حرارة الخليج، ماذا يجب على عضو الفريق أن يفعل بانتظام؟', 'أخذ فترات راحة مجدولة للترطيب في الظل أو الأماكن الباردة', 'الاستمرار في العمل دون توقف لإنهاء المناوبة بشكل أسرع', 'assets/quiz/heat_correct.jpg', 'assets/quiz/heat_incorrect.jpg'),
('heat_wellbeing', 'fr', 'En travaillant à l''extérieur sous la chaleur du Golfe, que doit faire régulièrement un membre de l''équipe ?', 'Prendre des pauses d''hydratation programmées à l''ombre ou dans des zones fraîches', 'Continuer sans pause pour terminer le service plus vite', 'assets/quiz/heat_correct.jpg', 'assets/quiz/heat_incorrect.jpg'),
('heat_wellbeing', 'sw', 'Wakati wa kufanya kazi nje katika joto la Ghuba, mwanachama wa timu anapaswa kufanya nini mara kwa mara?', 'Kupumzika kwa ratiba ili kunywa maji sehemu yenye kivuli au baridi', 'Kuendelea kufanya kazi bila mapumziko ili kumaliza zamu haraka', 'assets/quiz/heat_correct.jpg', 'assets/quiz/heat_incorrect.jpg'),
('cultural_legal', 'en', 'When deployed to a new country, what should a team member do about local customs and laws?', 'Learn and respect local cultural and legal requirements before starting', 'Assume the same rules from home apply everywhere', 'assets/quiz/culture_correct.jpg', 'assets/quiz/culture_incorrect.jpg'),
('cultural_legal', 'ar', 'عند الانتشار في بلد جديد، ماذا يجب على عضو الفريق أن يفعل بخصوص العادات والقوانين المحلية؟', 'التعرف على المتطلبات الثقافية والقانونية المحلية واحترامها قبل البدء', 'افتراض أن نفس القواعد من بلده الأصلي تنطبق في كل مكان', 'assets/quiz/culture_correct.jpg', 'assets/quiz/culture_incorrect.jpg'),
('cultural_legal', 'fr', 'Lors d''un déploiement dans un nouveau pays, que doit faire un membre de l''équipe concernant les coutumes et lois locales ?', 'Apprendre et respecter les exigences culturelles et légales locales avant de commencer', 'Supposer que les mêmes règles de son pays d''origine s''appliquent partout', 'assets/quiz/culture_correct.jpg', 'assets/quiz/culture_incorrect.jpg'),
('cultural_legal', 'sw', 'Anapopelekwa nchi mpya, mwanachama wa timu anapaswa kufanya nini kuhusu desturi na sheria za huko?', 'Kujifunza na kuheshimu mahitaji ya kitamaduni na kisheria ya eneo hilo kabla ya kuanza', 'Kudhani kuwa sheria zile zile za nyumbani zinatumika kila mahali', 'assets/quiz/culture_correct.jpg', 'assets/quiz/culture_incorrect.jpg'),
('data_protection', 'en', 'What should you do with photos or footage taken on a client or event site?', 'Keep it confidential and only share it through approved channels', 'Post it on personal social media right away', 'assets/quiz/data_correct.jpg', 'assets/quiz/data_incorrect.jpg'),
('data_protection', 'ar', 'ماذا يجب أن تفعل بالصور أو التسجيلات الملتقطة في موقع العميل أو الفعالية؟', 'الحفاظ على سريتها ومشاركتها فقط عبر القنوات المعتمدة', 'نشرها فوراً على وسائل التواصل الاجتماعي الشخصية', 'assets/quiz/data_correct.jpg', 'assets/quiz/data_incorrect.jpg'),
('data_protection', 'fr', 'Que devez-vous faire des photos ou vidéos prises sur le site d''un client ou d''un événement ?', 'Les garder confidentielles et ne les partager que via les canaux approuvés', 'Les publier immédiatement sur ses réseaux sociaux personnels', 'assets/quiz/data_correct.jpg', 'assets/quiz/data_incorrect.jpg'),
('data_protection', 'sw', 'Unapaswa kufanya nini na picha au video zilizopigwa eneo la mteja au tukio?', 'Kuzitunza kwa siri na kuzishiriki tu kupitia njia zilizoidhinishwa', 'Kuzichapisha mara moja kwenye mitandao ya kijamii binafsi', 'assets/quiz/data_correct.jpg', 'assets/quiz/data_incorrect.jpg'),
('anti_bribery', 'en', 'Someone offers you cash to skip a required safety check or look the other way on a rule. What should you do?', 'Politely refuse and report the offer to your supervisor', 'Accept it quietly since no one will notice', 'assets/quiz/bribery_correct.jpg', 'assets/quiz/bribery_incorrect.jpg'),
('anti_bribery', 'ar', 'عرض عليك شخص ما نقوداً لتخطي فحص سلامة مطلوب أو التغاضي عن قاعدة. ماذا يجب أن تفعل؟', 'الرفض بأدب والإبلاغ عن العرض للمشرف', 'قبولها بهدوء لأن لا أحد سيلاحظ', 'assets/quiz/bribery_correct.jpg', 'assets/quiz/bribery_incorrect.jpg'),
('anti_bribery', 'fr', 'Quelqu''un vous offre de l''argent pour sauter un contrôle de sécurité requis ou fermer les yeux sur une règle. Que devez-vous faire ?', 'Refuser poliment et signaler l''offre à votre superviseur', 'L''accepter discrètement puisque personne ne le remarquera', 'assets/quiz/bribery_correct.jpg', 'assets/quiz/bribery_incorrect.jpg'),
('anti_bribery', 'sw', 'Mtu anakupa pesa taslimu ili kuruka ukaguzi wa usalama unaohitajika au kupuuza sheria. Unapaswa kufanya nini?', 'Kukataa kwa heshima na kuripoti ofa hiyo kwa msimamizi wako', 'Kukubali kwa siri kwa sababu hakuna atakayegundua', 'assets/quiz/bribery_correct.jpg', 'assets/quiz/bribery_incorrect.jpg'),
('manual_handling', 'en', 'You need to move a heavy box on-site. What''s the correct approach?', 'Bend at the knees, keep the load close, and get help if it''s too heavy', 'Bend from the waist and twist quickly to get it done faster', 'assets/quiz/manual_correct.jpg', 'assets/quiz/manual_incorrect.jpg'),
('manual_handling', 'ar', 'تحتاج إلى نقل صندوق ثقيل في الموقع. ما هو النهج الصحيح؟', 'الانحناء من الركبتين، وإبقاء الحمل قريباً، وطلب المساعدة إذا كان ثقيلاً جداً', 'الانحناء من الخصر والالتفاف بسرعة لإنجاز الأمر بشكل أسرع', 'assets/quiz/manual_correct.jpg', 'assets/quiz/manual_incorrect.jpg'),
('manual_handling', 'fr', 'Vous devez déplacer une lourde caisse sur le site. Quelle est la bonne approche ?', 'Plier les genoux, garder la charge près du corps, et demander de l''aide si c''est trop lourd', 'Se plier au niveau de la taille et se tourner rapidement pour aller plus vite', 'assets/quiz/manual_correct.jpg', 'assets/quiz/manual_incorrect.jpg'),
('manual_handling', 'sw', 'Unahitaji kuhamisha sanduku zito eneo la kazi. Ni njia gani sahihi?', 'Kupinda magoti, kushikilia mzigo karibu na mwili, na kuomba msaada ikiwa ni mzito mno', 'Kupinda kiunoni na kugeuka haraka ili kumaliza haraka', 'assets/quiz/manual_correct.jpg', 'assets/quiz/manual_incorrect.jpg'),
('working_at_height', 'en', 'Before using a ladder on site, what must you do?', 'Inspect it and place it on stable, level ground', 'Use it as-is on whatever surface is nearby', 'assets/quiz/height_correct.jpg', 'assets/quiz/height_incorrect.jpg'),
('working_at_height', 'ar', 'قبل استخدام سلم في الموقع، ماذا يجب أن تفعل؟', 'فحصه ووضعه على أرض مستقرة ومستوية', 'استخدامه كما هو على أي سطح قريب', 'assets/quiz/height_correct.jpg', 'assets/quiz/height_incorrect.jpg'),
('working_at_height', 'fr', 'Avant d''utiliser une échelle sur site, que devez-vous faire ?', 'L''inspecter et la placer sur un sol stable et de niveau', 'L''utiliser telle quelle sur la surface la plus proche', 'assets/quiz/height_correct.jpg', 'assets/quiz/height_incorrect.jpg'),
('working_at_height', 'sw', 'Kabla ya kutumia ngazi eneo la kazi, unapaswa kufanya nini?', 'Kuikagua na kuiweka juu ya ardhi imara na tambarare', 'Kuitumia jinsi ilivyo juu ya uso wowote wa karibu', 'assets/quiz/height_correct.jpg', 'assets/quiz/height_incorrect.jpg'),
('electrical_safety', 'en', 'You notice a damaged power cable crossing a walkway. What should you do?', 'Tag it, report it immediately, and keep people away from it', 'Step over it carefully and carry on with your task', 'assets/quiz/electrical_correct.jpg', 'assets/quiz/electrical_incorrect.jpg'),
('electrical_safety', 'ar', 'لاحظت وجود كابل كهربائي تالف يعبر ممراً. ماذا يجب أن تفعل؟', 'وضع علامة عليه، والإبلاغ عنه فوراً، وإبعاد الناس عنه', 'التخطي فوقه بحذر ومواصلة مهمتك', 'assets/quiz/electrical_correct.jpg', 'assets/quiz/electrical_incorrect.jpg'),
('electrical_safety', 'fr', 'Vous remarquez un câble électrique endommagé traversant un passage. Que devez-vous faire ?', 'Le signaler avec une étiquette, le rapporter immédiatement, et éloigner les gens', 'Enjamber prudemment et continuer votre tâche', 'assets/quiz/electrical_correct.jpg', 'assets/quiz/electrical_incorrect.jpg'),
('electrical_safety', 'sw', 'Umeona nyaya ya umeme iliyoharibika ikivuka njia ya kupita. Unapaswa kufanya nini?', 'Kuiwekea alama, kuripoti mara moja, na kuwazuia watu wasikaribie', 'Kuruka juu yake kwa uangalifu na kuendelea na kazi yako', 'assets/quiz/electrical_correct.jpg', 'assets/quiz/electrical_incorrect.jpg'),
('slips_trips_falls', 'en', 'You spot loose cable lying across a busy walkway. What''s the right action?', 'Report it and have it properly covered or ramped immediately', 'Leave it — someone else will probably notice and deal with it', 'assets/quiz/slips_correct.jpg', 'assets/quiz/slips_incorrect.jpg'),
('slips_trips_falls', 'ar', 'لاحظت كابلاً مفكوكاً ممتداً عبر ممر مزدحم. ما هو الإجراء الصحيح؟', 'الإبلاغ عنه وتغطيته أو تسويته بشكل صحيح فوراً', 'تركه — على الأرجح سيلاحظه شخص آخر ويتعامل معه', 'assets/quiz/slips_correct.jpg', 'assets/quiz/slips_incorrect.jpg'),
('slips_trips_falls', 'fr', 'Vous repérez un câble détaché traversant un passage fréquenté. Quelle est la bonne action ?', 'Le signaler et le faire immédiatement couvrir ou aplanir correctement', 'Le laisser — quelqu''un d''autre le remarquera probablement', 'assets/quiz/slips_correct.jpg', 'assets/quiz/slips_incorrect.jpg'),
('slips_trips_falls', 'sw', 'Umeona nyaya iliyolegea ikivuka njia yenye watu wengi. Ni hatua gani sahihi?', 'Kuripoti na kuhakikisha imefunikwa au kunyooshwa vizuri mara moja', 'Kuiacha — pengine mtu mwingine ataigundua na kuishughulikia', 'assets/quiz/slips_correct.jpg', 'assets/quiz/slips_incorrect.jpg'),
('vehicle_loading', 'en', 'A forklift is reversing near you in the loading bay. What should you do?', 'Make eye contact with the driver before crossing its path', 'Assume the driver has seen you and keep walking', 'assets/quiz/vehicle_correct.jpg', 'assets/quiz/vehicle_incorrect.jpg'),
('vehicle_loading', 'ar', 'رافعة شوكية تتراجع بالقرب منك في منطقة التحميل. ماذا يجب أن تفعل؟', 'التواصل بالعين مع السائق قبل عبور مساره', 'افتراض أن السائق قد رآك ومواصلة المشي', 'assets/quiz/vehicle_correct.jpg', 'assets/quiz/vehicle_incorrect.jpg'),
('vehicle_loading', 'fr', 'Un chariot élévateur recule près de vous dans la zone de chargement. Que devez-vous faire ?', 'Établir un contact visuel avec le conducteur avant de traverser son chemin', 'Supposer que le conducteur vous a vu et continuer à marcher', 'assets/quiz/vehicle_correct.jpg', 'assets/quiz/vehicle_incorrect.jpg'),
('vehicle_loading', 'sw', 'Forklift inarudi nyuma karibu na wewe eneo la kupakia. Unapaswa kufanya nini?', 'Kuwasiliana kwa macho na dereva kabla ya kuvuka njia yake', 'Kudhani dereva amekuona na kuendelea kutembea', 'assets/quiz/vehicle_correct.jpg', 'assets/quiz/vehicle_incorrect.jpg'),
('first_aid', 'en', 'A colleague collapses on site. What is the correct first response?', 'Call the on-site medical team or first aider immediately and stay with them', 'Move them to a more comfortable spot straight away', 'assets/quiz/firstaid_correct.jpg', 'assets/quiz/firstaid_incorrect.jpg'),
('first_aid', 'ar', 'انهار أحد الزملاء في الموقع. ما هو الاستجابة الأولى الصحيحة؟', 'الاتصال بفريق الطب الميداني أو المسعف فوراً والبقاء معه', 'نقله إلى مكان أكثر راحة على الفور', 'assets/quiz/firstaid_correct.jpg', 'assets/quiz/firstaid_incorrect.jpg'),
('first_aid', 'fr', 'Un collègue s''effondre sur le site. Quelle est la première réaction correcte ?', 'Appeler immédiatement l''équipe médicale ou le secouriste et rester avec la personne', 'Le déplacer immédiatement vers un endroit plus confortable', 'assets/quiz/firstaid_correct.jpg', 'assets/quiz/firstaid_incorrect.jpg'),
('first_aid', 'sw', 'Mfanyakazi mwenzako anaanguka ghafla eneo la kazi. Ni hatua gani sahihi ya kwanza?', 'Kupiga simu timu ya matibabu au msaidizi wa huduma ya kwanza mara moja na kubaki naye', 'Kumhamishia mahali pazuri zaidi mara moja', 'assets/quiz/firstaid_correct.jpg', 'assets/quiz/firstaid_incorrect.jpg')
